          </svg>

          {/* Central Sculpted Sanctuary Portal */}
          <div
            ref={portalRef}
            className="ocular-portal-shell"
            onPointerEnter={() => setIsHoveringPortal(true)}
            onPointerLeave={() => {
              setIsHoveringPortal(false);
              setParallax({ x: 0, y: 0 });
