                  alt={activeRefractData.title}
                  className="portal-refracted-image"
                  style={{
                    transform: `scale(1.22) translate3d(${(50 - lensPos.x) * 0.45}px, ${
                      (50 - lensPos.y) * 0.45
                    }px, 0)`,
