                <div className="satellite-caption">
                  <span className="sat-roman">{sat.roman}</span>
                  <div className="sat-text">
                    <span className="sat-title">{sat.label}</span>
                    <span className="sat-sub">{sat.sublabel}</span>
                  </div>
                </div>
              </button>
