/* ==========================================================================
   MAISON ELYSIAN — SURREALIST EDITORIAL LUXURY DESIGN SYSTEM
   ========================================================================== */

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --font-display: 'Cinzel', 'Cormorant Garamond', Georgia, serif;
  --font-decorative: 'Cinzel Decorative', 'Cinzel', serif;
  --font-editorial: 'Cormorant Garamond', 'Instrument Serif', Georgia, serif;
  --font-mono: 'JetBrains Mono', monospace;

  --bg-primary: #061519;
  --bg-elevated: #0c242b;
  --accent-gold: #f4a900;
  --accent-coral: #ff6e7a;
  --text-primary: #f6f2e9;
  --text-muted: #99b3b9;
  --glow-aura: rgba(244, 169, 0, 0.24);
  --border-brass: rgba(244, 169, 0, 0.28);
  --border-subtle: rgba(246, 242, 233, 0.12);
}

html {
  scroll-behavior: smooth;
  background-color: #061519;
  color: #f6f2e9;
}

body {
  font-family: var(--font-editorial);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

.elysian-universe {
  min-height: 100vh;
  background:
    radial-gradient(circle at 75% 15%, var(--glow-aura), transparent 45%),
    radial-gradient(circle at 18% 60%, rgba(255, 110, 122, 0.11), transparent 50%),
    linear-gradient(180deg, var(--bg-primary) 0%, var(--bg-elevated) 52%, var(--bg-primary) 100%);
  color: var(--text-primary);
  position: relative;
  transition: background-color 0.6s ease, color 0.5s ease;
}

/* Subtle tactile grain overlay */
.atmospheric-grain-overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 90;
  opacity: 0.035;
  background-image: radial-gradient(rgba(255, 255, 255, 0.75) 0.65px, transparent 0.65px);
  background-size: 3px 3px;
}

/* ==========================================================================
   FLOATING ASTROLABE HEADER
   ========================================================================== */

.surreal-header {
  position: sticky;
  top: 0;
  z-index: 100;
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  background: linear-gradient(
    180deg,
    rgba(6, 21, 25, 0.88) 0%,
    rgba(6, 21, 25, 0.68) 100%
  );
  border-bottom: 1px solid var(--border-brass);
}

.header-inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0.75rem 1.75rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.maison-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
  color: var(--text-primary);
}

.maison-emblem {
  width: 34px;
  height: 34px;
  color: var(--accent-gold);
  display: inline-flex;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.maison-brand:hover .maison-emblem {
  transform: rotate(90deg) scale(1.06);
}

.maison-brand-text {
  display: flex;
  flex-direction: column;
}

.maison-name {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: 0.28em;
  color: var(--text-primary);
}

.maison-sub {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
}

.archival-nav {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  padding: 0.25rem 0.5rem;
}

.nav-chapter {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.35rem 0.75rem;
  border-radius: 999px;
  text-decoration: none;
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.74rem;
  letter-spacing: 0.1em;
  transition: all 0.25s ease;
}

.nav-chapter:hover {
  color: var(--text-primary);
  background: rgba(244, 169, 0, 0.14);
}

.chapter-roman {
  color: var(--accent-gold);
  font-weight: 600;
  font-size: 0.68rem;
}

.header-instruments {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  flex-wrap: wrap;
}

.telemetry-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  padding: 0.32rem 0.68rem;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: rgba(0, 0, 0, 0.25);
}

.telemetry-icon {
  color: var(--accent-gold);
}

.atmosphere-switcher {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.2rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
  background: rgba(0, 0, 0, 0.32);
}

.atm-dot-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.24rem 0.52rem;
  border-radius: 999px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-family: var(--font-mono);
  font-size: 0.65rem;
  transition: all 0.2s ease;
}

.atm-dot-btn.active {
  background: rgba(244, 169, 0, 0.22);
  color: var(--text-primary);
}

.atm-swatch {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.relic-counter-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  padding: 0.34rem 0.72rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 110, 122, 0.45);
  background: rgba(255, 110, 122, 0.12);
  color: var(--text-primary);
  text-decoration: none;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  transition: all 0.25s ease;
}

.relic-counter-pill:hover {
  background: rgba(255, 110, 122, 0.24);
  transform: translateY(-1px);
}

.sound-toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  padding: 0.34rem 0.72rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
  background: rgba(244, 169, 0, 0.08);
  color: var(--accent-gold);
  cursor: pointer;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  transition: all 0.25s ease;
}

.sound-toggle-btn.active {
  background: var(--accent-gold);
  color: #061519;
  font-weight: 500;
}

/* ==========================================================================
   CHAPTER I: HERO WUNDERKAMMER & DUAL-REALITY OCULAR LOUPE
   ========================================================================== */

.hero-wunderkammer {
  position: relative;
  min-height: calc(100vh - 64px);
  padding: 3rem 1.75rem 4.5rem;
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-architectural-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.22;
}

.grid-meridian-v {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 52%;
  width: 1px;
  background: linear-gradient(180deg, transparent, var(--accent-gold), transparent);
}

.grid-meridian-h {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--accent-gold), transparent);
}

.hero-layout-container {
  max-width: 1440px;
  width: 100%;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.05fr 1.15fr;
  gap: 3.25rem;
  align-items: center;
  position: relative;
  z-index: 2;
}

.hero-editorial-column {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.maison-archival-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  align-self: flex-start;
  padding: 0.38rem 0.9rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
  background: rgba(12, 36, 43, 0.72);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.12em;
  color: var(--accent-gold);
}

.badge-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent-coral);
  box-shadow: 0 0 10px var(--accent-coral);
}

.badge-sep {
  opacity: 0.45;
}

.badge-coord {
  color: var(--text-muted);
}

.hero-title-lockup {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.hero-overtitle {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-family: var(--font-display);
  font-size: 0.78rem;
  letter-spacing: 0.24em;
  color: var(--accent-coral);
  text-transform: uppercase;
}

.overtitle-ornament {
  color: var(--accent-gold);
}

.hero-primary-title {
  font-family: var(--font-decorative);
  font-size: clamp(2.75rem, 5.2vw, 4.9rem);
  font-weight: 700;
  line-height: 1.02;
  letter-spacing: 0.03em;
  background: linear-gradient(
    125deg,
    #ffffff 0%,
    #f6f2e9 35%,
    var(--accent-gold) 72%,
    var(--accent-coral) 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
}

.hero-subtitle-bar {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  margin-top: 0.35rem;
}

.subtitle-line {
  width: 48px;
  height: 1px;
  background: var(--accent-gold);
  flex-shrink: 0;
}

.hero-brand-declaration {
  font-family: var(--font-display);
  font-size: 0.96rem;
  letter-spacing: 0.1em;
  color: var(--text-primary);
}

.hero-brand-declaration strong {
  color: var(--accent-gold);
  letter-spacing: 0.22em;
}

.hero-lead-prose {
  font-size: 1.24rem;
  line-height: 1.62;
  color: var(--text-muted);
  max-width: 58ch;
  font-weight: 400;
}

.hero-lead-prose em {
  color: var(--text-primary);
  font-style: italic;
}

/* Interactive Instrument Panel inside Hero */
.hero-instrument-panel {
  background: linear-gradient(145deg, rgba(12, 36, 43, 0.84), rgba(6, 21, 25, 0.92));
  border: 1px solid var(--border-brass);
  border-radius: 18px;
  padding: 1.15rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.42);
}

.instrument-group {
  display: flex;
  flex-direction: column;
  gap: 0.48rem;
}

.instrument-label {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent-gold);
}

.realm-pill-selector,
.shape-pill-selector {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.realm-pill-btn,
.shape-pill-btn {
  padding: 0.42rem 0.78rem;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.03);
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.74rem;
  letter-spacing: 0.06em;
  cursor: pointer;
  transition: all 0.22s ease;
}

.realm-pill-btn:hover,
.shape-pill-btn:hover {
  border-color: var(--accent-gold);
  color: var(--text-primary);
}

.realm-pill-btn.active {
  background: linear-gradient(135deg, var(--accent-gold), var(--accent-coral));
  color: #061519;
  border-color: transparent;
  font-weight: 700;
}

.shape-pill-btn.active {
  background: rgba(244, 169, 0, 0.2);
  border-color: var(--accent-gold);
  color: var(--text-primary);
}

.instrument-row-split {
  display: grid;
  grid-template-columns: 1.2fr 0.9fr;
  gap: 1rem;
  align-items: end;
}

.brass-range-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 5px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent-gold), var(--accent-coral));
  outline: none;
  cursor: pointer;
}

.brass-range-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #f6f2e9;
  border: 2px solid var(--accent-gold);
  box-shadow: 0 0 12px rgba(244, 169, 0, 0.8);
  cursor: grab;
}

.hero-cta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  align-items: center;
}

.btn-elysian-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  padding: 0.88rem 1.55rem;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--accent-gold) 0%, #ff9233 55%, var(--accent-coral) 100%);
  color: #061519;
  font-family: var(--font-display);
  font-size: 0.84rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  border: none;
  cursor: pointer;
  box-shadow: 0 12px 32px rgba(244, 169, 0, 0.3);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.btn-elysian-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 16px 38px rgba(255, 110, 122, 0.42);
}

.btn-elysian-ghost {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.85rem 1.4rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
  background: rgba(12, 36, 43, 0.55);
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.25s ease;
}

.btn-elysian-ghost:hover {
  border-color: var(--accent-gold);
  background: rgba(244, 169, 0, 0.14);
}

/* Right Collage Stage: Portal + Astrolabe + 4 Cropped Satellites */
.hero-collage-stage {
  position: relative;
  min-height: 640px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.astrolabe-halo-outer {
  position: absolute;
  width: 610px;
  height: 610px;
  color: var(--accent-gold);
  pointer-events: none;
  z-index: 1;
}

.astrolabe-svg-spin {
  width: 100%;
  height: 100%;
  animation: slowAstrolabeRotate 68s linear infinite;
}

@keyframes slowAstrolabeRotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.stage-connector-lines {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 2;
}

.ocular-portal-shell {
  position: relative;
  width: min(470px, 86vw);
  height: 550px;
  z-index: 3;
  cursor: crosshair;
  filter: drop-shadow(0 28px 60px rgba(0, 0, 0, 0.72))
    drop-shadow(0 0 2px rgba(244, 169, 0, 0.65));
  transition: transform 0.18s ease-out;
}

.ocular-portal-clipped {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #061519;
}

.portal-base-image,
.portal-refracted-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
  transition: transform 0.15s ease-out;
}

.portal-alchemical-wash {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at center,
    transparent 45%,
    rgba(6, 21, 25, 0.58) 100%
  );
  pointer-events: none;
}

.portal-refraction-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

.ocular-loupe-reticle {
  position: absolute;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1.5px solid var(--accent-gold);
  box-shadow:
    0 0 30px rgba(244, 169, 0, 0.38),
    inset 0 0 24px rgba(255, 110, 122, 0.28);
  pointer-events: none;
  z-index: 4;
}

.reticle-ring-inner {
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  border: 1px dashed rgba(255, 255, 255, 0.45);
}

.reticle-crosshair-h {
  position: absolute;
  left: -10px;
  right: -10px;
  top: 50%;
  height: 1px;
  background: rgba(244, 169, 0, 0.45);
}

.reticle-crosshair-v {
  position: absolute;
  top: -10px;
  bottom: -10px;
  left: 50%;
  width: 1px;
  background: rgba(244, 169, 0, 0.45);
}

.reticle-tag {
  position: absolute;
  bottom: -24px;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  background: rgba(6, 21, 25, 0.9);
  border: 1px solid var(--accent-gold);
  padding: 0.15rem 0.55rem;
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 0.6rem;
  letter-spacing: 0.08em;
  color: var(--accent-gold);
}

.portal-inscription-footer {
  position: absolute;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 5;
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.3rem 0.85rem;
  border-radius: 999px;
  background: rgba(6, 21, 25, 0.85);
  border: 1px solid var(--border-brass);
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.1em;
  color: var(--text-primary);
  white-space: nowrap;
}

/* 4 Orbiting Cropped Collage Satellites */
.collage-satellite {
  position: absolute;
  z-index: 6;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--text-primary);
  transition: transform 0.25s ease;
}

.collage-satellite:hover {
  transform: scale(1.06) !important;
}

.satellite-image-crop {
  width: 112px;
  height: 128px;
  background-repeat: no-repeat;
  filter: drop-shadow(0 14px 28px rgba(0, 0, 0, 0.75))
    drop-shadow(0 0 2px var(--accent-gold));
  transition: filter 0.25s ease;
}

.collage-satellite.active .satellite-image-crop {
  filter: drop-shadow(0 16px 32px rgba(255, 110, 122, 0.55))
    drop-shadow(0 0 3px var(--accent-coral));
}

.satellite-caption {
  display: flex;
  align-items: center;
  gap: 0.42rem;
  padding: 0.26rem 0.65rem;
  border-radius: 999px;
  background: rgba(6, 21, 25, 0.92);
  border: 1px solid var(--border-brass);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.5);
}

.collage-satellite.active .satellite-caption {
  border-color: var(--accent-coral);
  background: rgba(255, 110, 122, 0.18);
}

.sat-roman {
  font-family: var(--font-display);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--accent-gold);
}

.sat-text {
  display: flex;
  flex-direction: column;
  text-align: left;
}

.sat-title {
  font-family: var(--font-display);
  font-size: 0.68rem;
  letter-spacing: 0.06em;
  color: var(--text-primary);
}

.sat-sub {
  font-family: var(--font-mono);
  font-size: 0.56rem;
  color: var(--text-muted);
}

.sat-top-left {
  top: 14px;
  left: 6px;
}

.sat-top-right {
  top: 22px;
  right: 6px;
}

.sat-bottom-left {
  bottom: 18px;
  left: 10px;
}

.sat-bottom-right {
  bottom: 22px;
  right: 10px;
}

/* ==========================================================================
   LAPIDARY MARQUEE RIBBON & MEANDER DIVIDER
   ========================================================================== */

.lapidary-ribbon {
  position: relative;
  background: rgba(6, 21, 25, 0.85);
  padding: 0.5rem 0;
  overflow: hidden;
}

.meander-divider {
  width: 100%;
  height: 16px;
  color: var(--accent-gold);
}

.meander-svg {
  width: 100%;
  height: 100%;
}

.ribbon-marquee-track {
  display: flex;
  gap: 2.5rem;
  white-space: nowrap;
  padding: 0.55rem 0;
  font-family: var(--font-display);
  font-size: 0.78rem;
  letter-spacing: 0.28em;
  color: var(--accent-gold);
  animation: ribbonScroll 38s linear infinite;
}

@keyframes ribbonScroll {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* ==========================================================================
   SHARED SECTION HEADER ARCHITECTURE
   ========================================================================== */

.section-header-block {
  max-width: 1400px;
  margin: 0 auto 2.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.section-kicker-row {
  display: flex;
  align-items: center;
  gap: 1rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
}

.kicker-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, var(--border-brass), transparent);
}

.kicker-coords {
  color: var(--accent-coral);
}

.section-title-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: end;
}

.section-display-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 3.6vw, 3.25rem);
  font-weight: 600;
  letter-spacing: 0.04em;
  line-height: 1.1;
  color: var(--text-primary);
}

.section-editorial-deck {
  font-size: 1.16rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* ==========================================================================
   CHAPTER II: CABINET DISSECTION (INTERACTIVE SPECIMEN EXCAVATION)
   ========================================================================== */

.cabinet-dissection-section {
  padding: 5.5rem 1.75rem;
  max-width: 1440px;
  margin: 0 auto;
}

.dissection-workbench {
  display: grid;
  grid-template-columns: 1.38fr 0.92fr;
  gap: 2.25rem;
  align-items: start;
}

.dissection-canvas-column {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.wunderkammer-frame-wrapper {
  background: rgba(12, 36, 43, 0.55);
  border: 1px solid var(--border-brass);
  border-radius: 24px;
  padding: 1.1rem;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.5);
}

.canvas-hud-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.85rem;
  flex-wrap: wrap;
}

.hud-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  color: var(--accent-gold);
}

.hud-zoom-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.36rem 0.85rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
  background: rgba(244, 169, 0, 0.1);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.hud-zoom-btn.active {
  background: var(--accent-gold);
  color: #061519;
  font-weight: 600;
}

/* Sculpted Octagonal/Pediment Stage */
.wunderkammer-clipped-stage {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9.2;
  clip-path: url(#clip-wunderkammer-stage);
  overflow: hidden;
  background: #051114;
}

.wunderkammer-pan-layer {
  position: relative;
  width: 100%;
  height: 100%;
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.wunderkammer-master-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.constellation-svg-overlay {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.specimen-pin {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1.5px solid var(--accent-gold);
  background: rgba(6, 21, 25, 0.88);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 4;
  transition: all 0.25s ease;
}

.specimen-pin:hover,
.specimen-pin.active {
  background: var(--accent-coral);
  border-color: #ffffff;
  color: #061519;
  transform: translate(-50%, -50%) scale(1.18);
  z-index: 6;
}

.pin-pulse-ring {
  position: absolute;
  inset: -6px;
  border-radius: 50%;
  border: 1px solid var(--accent-gold);
  animation: pinPulse 2.4s ease-out infinite;
  pointer-events: none;
}

@keyframes pinPulse {
  0% {
    transform: scale(0.85);
    opacity: 0.9;
  }
  100% {
    transform: scale(1.55);
    opacity: 0;
  }
}

.pin-floating-label {
  position: absolute;
  top: 112%;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  padding: 0.18rem 0.55rem;
  border-radius: 999px;
  background: rgba(6, 21, 25, 0.92);
  border: 1px solid var(--border-brass);
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 0.62rem;
  letter-spacing: 0.06em;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.specimen-pin:hover .pin-floating-label,
.specimen-pin.active .pin-floating-label {
  opacity: 1;
}

/* 6 Extracted Cut-Out Medallions Strip */
.extracted-medallions-strip {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0.8rem;
}

.medallion-cutout-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  padding: 0.65rem 0.45rem;
  border-radius: 16px;
  border: 1px solid var(--border-subtle);
  background: rgba(12, 36, 43, 0.45);
  color: var(--text-primary);
  cursor: pointer;
  transition: all 0.25s ease;
}

.medallion-cutout-card:hover,
.medallion-cutout-card.active {
  border-color: var(--accent-gold);
  background: rgba(244, 169, 0, 0.14);
  transform: translateY(-3px);
}

.medallion-shape-frame {
  position: relative;
  width: 78px;
  height: 88px;
}

.medallion-cropped-art {
  width: 100%;
  height: 100%;
  background-repeat: no-repeat;
  filter: drop-shadow(0 6px 14px rgba(0, 0, 0, 0.6));
}

.medallion-saved-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent-coral);
  color: #061519;
  font-size: 0.62rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.medallion-num {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  color: var(--accent-gold);
}

.medallion-name {
  font-family: var(--font-display);
  font-size: 0.66rem;
  text-align: center;
  line-height: 1.25;
}

/* Right Curatorial Specimen Dossier Card */
.specimen-dossier-panel {
  background: linear-gradient(160deg, rgba(12, 36, 43, 0.9), rgba(6, 21, 25, 0.96));
  border: 1px solid var(--border-brass);
  border-radius: 24px;
  padding: 1.65rem;
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
  box-shadow: 0 28px 64px rgba(0, 0, 0, 0.55);
}

.dossier-top-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.1em;
}

.dossier-number {
  color: var(--accent-gold);
}

.dossier-category {
  color: var(--accent-coral);
}

.dossier-magnifier-stage {
  position: relative;
  height: 215px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle, rgba(244, 169, 0, 0.16), transparent 70%);
  border-radius: 18px;
  border: 1px solid var(--border-subtle);
  overflow: hidden;
}

.dossier-sculpted-crop {
  width: 175px;
  height: 190px;
  background-repeat: no-repeat;
  filter: drop-shadow(0 16px 28px rgba(0, 0, 0, 0.75));
  transition: background-position 0.45s ease, clip-path 0.35s ease;
}

.dossier-coord-stamp {
  position: absolute;
  bottom: 10px;
  right: 12px;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  letter-spacing: 0.08em;
  color: var(--accent-gold);
  background: rgba(6, 21, 25, 0.85);
  padding: 0.2rem 0.5rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
}

.dossier-heading-group {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.dossier-latin {
  font-family: var(--font-editorial);
  font-style: italic;
  font-size: 0.98rem;
  color: var(--accent-coral);
}

.dossier-title {
  font-family: var(--font-display);
  font-size: 1.55rem;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

.dossier-epigraph {
  font-style: italic;
  font-size: 1.08rem;
  color: var(--accent-gold);
  border-left: 2px solid var(--accent-gold);
  padding-left: 0.85rem;
}

.dossier-curator-note {
  font-size: 1.05rem;
  color: var(--text-muted);
  line-height: 1.58;
}

.dossier-meta-block {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.meta-block-label {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  color: var(--text-muted);
}

.accord-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.accord-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  padding: 0.28rem 0.65rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
  background: rgba(244, 169, 0, 0.08);
  font-family: var(--font-display);
  font-size: 0.7rem;
  color: var(--text-primary);
}

.pigment-swatches-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
}

.pigment-chip {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.35rem 0.5rem;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid var(--border-subtle);
}

.pigment-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  flex-shrink: 0;
  border: 1px solid rgba(255, 255, 255, 0.35);
}

.pigment-info {
  display: flex;
  flex-direction: column;
}

.pigment-name {
  font-size: 0.72rem;
  line-height: 1.1;
}

.pigment-hex {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  color: var(--text-muted);
}

.btn-collect-specimen {
  margin-top: 0.35rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  padding: 0.85rem 1.2rem;
  border-radius: 999px;
  border: 1px solid var(--accent-gold);
  background: rgba(244, 169, 0, 0.14);
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 0.78rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.25s ease;
}

.btn-collect-specimen:hover {
  background: var(--accent-gold);
  color: #061519;
}

.btn-collect-specimen.collected {
  background: linear-gradient(135deg, var(--accent-coral), var(--accent-gold));
  border-color: transparent;
  color: #061519;
  font-weight: 700;
}

/* ==========================================================================
   CHAPTER III: LE PRISME DES HORIZONS (LOUVERS / ASTROLABE / PARAVENT)
   ========================================================================== */

.triptych-morph-section {
  padding: 5.5rem 1.75rem;
  max-width: 1440px;
  margin: 0 auto;
}

.prism-control-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
  padding: 1rem 1.35rem;
  border-radius: 20px;
  border: 1px solid var(--border-brass);
  background: rgba(12, 36, 43, 0.72);
  margin-bottom: 1.75rem;
}

.prism-mode-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.prism-tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.58rem 1.05rem;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.03);
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.76rem;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: all 0.25s ease;
}

.prism-tab-btn.active {
  background: var(--accent-gold);
  color: #061519;
  border-color: transparent;
  font-weight: 700;
}

.pendulum-scrubber-box {
  display: flex;
  align-items: center;
  gap: 1rem;
  min-width: 300px;
  flex: 1;
  max-width: 440px;
}

.pendulum-label {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--accent-gold);
}

.prism-stage-shell {
  position: relative;
  min-height: 540px;
  border-radius: 28px;
  border: 1px solid var(--border-brass);
  background: radial-gradient(circle at center, rgba(12, 36, 43, 0.9), rgba(4, 13, 18, 0.98));
  padding: 1.5rem;
  overflow: hidden;
  box-shadow: 0 30px 70px rgba(0, 0, 0, 0.6);
}

/* Mode 1: Fluted Column Louvers */
.louver-colonnade-stage {
  position: relative;
  height: 500px;
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 6px;
  cursor: ew-resize;
  clip-path: url(#clip-wunderkammer-stage);
}

.fluted-louver-slice {
  position: relative;
  height: 100%;
  border-radius: 999px;
  overflow: hidden;
  border: 1px solid rgba(244, 169, 0, 0.25);
  transition: transform 0.25s ease-out;
}

.louver-layer {
  position: absolute;
  inset: 0;
  background-size: 1200% 100%;
  background-repeat: no-repeat;
  transition: opacity 0.2s ease-out;
}

.fluted-specular-groove {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(0, 0, 0, 0.45) 0%,
    rgba(255, 255, 255, 0.14) 48%,
    rgba(0, 0, 0, 0.55) 100%
  );
  pointer-events: none;
}

.louver-roman-index {
  position: absolute;
  bottom: 14px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-mono);
  font-size: 0.58rem;
  color: var(--accent-gold);
  opacity: 0.75;
}

.stage-floating-whisper {
  position: absolute;
  bottom: 18px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.38rem 0.95rem;
  border-radius: 999px;
  background: rgba(6, 21, 25, 0.9);
  border: 1px solid var(--border-brass);
  font-family: var(--font-mono);
  font-size: 0.66rem;
  color: var(--accent-gold);
  pointer-events: none;
  white-space: nowrap;
}

/* Mode 2: Concentric Astrolabe Rings */
.concentric-astrolabe-stage {
  position: relative;
  height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: ew-resize;
}

.astrolabe-art-ring {
  position: absolute;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.65);
  transition: transform 0.2s ease-out;
}

.astrolabe-art-ring.ring-1 {
  width: 472px;
  height: 472px;
}

.astrolabe-art-ring.ring-2 {
  width: 364px;
  height: 364px;
}

.astrolabe-art-ring.ring-3 {
  width: 252px;
  height: 252px;
}

.astrolabe-art-ring.ring-4 {
  width: 140px;
  height: 140px;
}

.astrolabe-overlay-reticle {
  position: relative;
  width: 500px;
  height: 500px;
  pointer-events: none;
  z-index: 5;
}

/* Mode 3: Sculptural Paravent Folding Screen */
.paravent-folding-stage {
  display: flex;
  gap: 0.85rem;
  height: 500px;
  align-items: stretch;
}

.paravent-arch-panel {
  flex: 1;
  position: relative;
  cursor: pointer;
  transition: flex 0.55s cubic-bezier(0.22, 1, 0.36, 1), transform 0.45s ease;
}

.paravent-arch-panel.expanded {
  flex: 2.4;
}

.paravent-arch-mask {
  position: relative;
  width: 100%;
  height: 100%;
  clip-path: url(#clip-sanctuary-arch);
  overflow: hidden;
  background: #061519;
}

.paravent-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s ease;
}

.paravent-arch-panel:hover .paravent-img {
  transform: scale(1.06);
}

.paravent-gradient-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(6, 21, 25, 0.1) 20%, rgba(6, 21, 25, 0.92) 100%);
}

.paravent-panel-content {
  position: absolute;
  bottom: 22px;
  left: 20px;
  right: 20px;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.paravent-roman {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
}

.paravent-title {
  font-family: var(--font-display);
  font-size: 1.3rem;
  color: var(--text-primary);
}

.paravent-epoch {
  font-family: var(--font-editorial);
  font-style: italic;
  font-size: 0.95rem;
  color: var(--accent-coral);
}

.paravent-desc {
  font-size: 0.96rem;
  color: var(--text-muted);
  max-width: 48ch;
  margin-top: 0.25rem;
}

.paravent-coords {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.prism-telemetry-footer {
  margin-top: 1.4rem;
  padding: 1.25rem 1.5rem;
  border-radius: 20px;
  border: 1px solid var(--border-subtle);
  background: rgba(12, 36, 43, 0.55);
  display: grid;
  grid-template-columns: 1fr 1.4fr auto;
  gap: 1.5rem;
  align-items: center;
}

.summary-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  color: var(--accent-gold);
  border-left: 2px solid var(--accent-gold);
  padding-left: 0.5rem;
  margin-bottom: 0.25rem;
}

.summary-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
}

.summary-epoch {
  font-style: italic;
  color: var(--accent-coral);
  font-size: 0.95rem;
}

.summary-caption {
  font-size: 1.05rem;
  color: var(--text-muted);
}

.summary-coord-block {
  display: flex;
  flex-direction: column;
  text-align: right;
  font-family: var(--font-mono);
}

.coord-label {
  font-size: 0.58rem;
  color: var(--text-muted);
  letter-spacing: 0.12em;
}

.coord-value {
  font-size: 0.78rem;
  color: var(--accent-gold);
}

/* ==========================================================================
   CHAPTER IV: ALCHEMY COMPOSER & 4 ASSEMBLAGE RELIQUARIES
   ========================================================================== */

.alchemy-composer-section {
  padding: 5.5rem 1.75rem;
  max-width: 1440px;
  margin: 0 auto;
}

.editions-totem-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.35rem;
  margin-bottom: 3rem;
}

.edition-totem-card {
  background: linear-gradient(165deg, rgba(12, 36, 43, 0.78), rgba(6, 21, 25, 0.95));
  border: 1px solid var(--border-subtle);
  border-radius: 24px;
  padding: 1.35rem;
  display: flex;
  flex-direction: column;
  gap: 1.1rem;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}

.edition-totem-card:hover,
.edition-totem-card.active {
  border-color: var(--accent-gold);
  transform: translateY(-6px);
  box-shadow: 0 24px 50px rgba(0, 0, 0, 0.55);
}

.totem-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.12em;
}

.totem-roman {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.92rem;
}

.totem-volume {
  color: var(--text-muted);
}

.totem-art-assemblage {
  position: relative;
  height: 235px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.totem-halo-ring {
  position: absolute;
  width: 190px;
  height: 190px;
  border-radius: 50%;
  border: 1px dashed;
  opacity: 0.45;
  animation: slowAstrolabeRotate 45s linear infinite;
}

.totem-primary-vessel {
  width: 168px;
  height: 210px;
  background-repeat: no-repeat;
  z-index: 2;
  filter: drop-shadow(0 16px 28px rgba(0, 0, 0, 0.75));
  transition: transform 0.4s ease;
}

.edition-totem-card:hover .totem-primary-vessel {
  transform: scale(1.06);
}

.totem-secondary-seal {
  position: absolute;
  bottom: 10px;
  right: 16px;
  width: 74px;
  height: 74px;
  background-repeat: no-repeat;
  z-index: 3;
  filter: drop-shadow(0 8px 18px rgba(0, 0, 0, 0.8));
}

.totem-rarity-tag {
  position: absolute;
  bottom: 6px;
  left: 10px;
  z-index: 4;
  padding: 0.18rem 0.55rem;
  border-radius: 999px;
  background: rgba(6, 21, 25, 0.9);
  border: 1px solid var(--border-brass);
  font-family: var(--font-mono);
  font-size: 0.56rem;
  color: var(--accent-gold);
}

.totem-body {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.totem-designation {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  letter-spacing: 0.12em;
  color: var(--accent-coral);
  text-transform: uppercase;
}

.totem-title {
  font-family: var(--font-display);
  font-size: 1.32rem;
  color: var(--text-primary);
}

.totem-subtitle {
  font-style: italic;
  font-size: 0.98rem;
  color: var(--accent-gold);
}

.totem-story {
  font-size: 0.96rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.totem-accord-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.32rem;
  margin-top: 0.35rem;
}

.totem-accord-pill {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  padding: 0.2rem 0.5rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-subtle);
  color: var(--text-primary);
}

/* Alembic Transmutation Workbench */
.alembic-transmutation-bench {
  background: linear-gradient(145deg, rgba(12, 36, 43, 0.88), rgba(5, 16, 20, 0.96));
  border: 1px solid var(--border-brass);
  border-radius: 28px;
  padding: 2.25rem;
  display: grid;
  grid-template-columns: 1.15fr 0.95fr;
  gap: 2.5rem;
  align-items: center;
  box-shadow: 0 28px 68px rgba(0, 0, 0, 0.55);
}

.alembic-controls-col {
  display: flex;
  flex-direction: column;
  gap: 1.35rem;
}

.alembic-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  color: var(--accent-coral);
}

.alembic-title {
  font-family: var(--font-display);
  font-size: 1.85rem;
  margin-top: 0.25rem;
}

.alembic-desc {
  font-size: 1.06rem;
  color: var(--text-muted);
}

.alembic-sliders-stack {
  display: flex;
  flex-direction: column;
  gap: 0.95rem;
}

.alembic-slider-item {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.slider-meta-row {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-display);
  font-size: 0.82rem;
}

.slider-pct {
  font-family: var(--font-mono);
  color: var(--accent-gold);
}

.alembic-action-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem;
  margin-top: 0.35rem;
}

.btn-wax-seal {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  padding: 0.88rem 1.35rem;
  border-radius: 999px;
  border: 1px solid var(--accent-coral);
  background: linear-gradient(135deg, var(--accent-coral), var(--accent-gold));
  color: #061519;
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: transform 0.2s ease;
}

.btn-wax-seal.sealed {
  background: var(--accent-gold);
}

.btn-reset-alembic {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.85rem 1.15rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
  background: transparent;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  cursor: pointer;
}

.alembic-seal-preview-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.15rem;
}

.composite-emblem-stage {
  position: relative;
  width: 340px;
  height: 340px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.emblem-layer {
  position: absolute;
  width: 310px;
  height: 310px;
  background-repeat: no-repeat;
  filter: drop-shadow(0 12px 24px rgba(0, 0, 0, 0.7));
  transition: transform 0.25s ease-out, background-position 0.25s ease-out;
}

.emblem-engraved-ring {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 6;
}

.wax-seal-stamp-badge {
  position: absolute;
  bottom: 12px;
  z-index: 8;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.35rem 0.9rem;
  border-radius: 999px;
  background: var(--accent-coral);
  color: #061519;
  font-family: var(--font-mono);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  box-shadow: 0 8px 24px rgba(255, 110, 122, 0.6);
}

.emblem-formula-readout {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.formula-code-tag {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
}

.formula-latin-title {
  font-family: var(--font-display);
  font-size: 1.18rem;
  letter-spacing: 0.08em;
}

.formula-ratio-line {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--text-muted);
}

/* ==========================================================================
   CHAPTER V: LE SEUIL DU NAOS & PATRONAGE LEDGER
   ========================================================================== */

.naos-portal-section {
  padding: 5.5rem 1.75rem 6rem;
  max-width: 1440px;
  margin: 0 auto;
}

.naos-architectural-theatre {
  background: linear-gradient(180deg, rgba(8, 24, 30, 0.8), rgba(4, 12, 16, 0.96));
  border: 1px solid var(--border-brass);
  border-radius: 28px;
  padding: 1.5rem;
  margin-bottom: 2.5rem;
  box-shadow: 0 32px 80px rgba(0, 0, 0, 0.65);
}

.naos-aperture-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  flex-wrap: wrap;
  margin-bottom: 1.25rem;
}

.naos-slider-label {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  color: var(--accent-gold);
}

.btn-open-full-naos {
  padding: 0.48rem 1rem;
  border-radius: 999px;
  border: 1px solid var(--accent-gold);
  background: rgba(244, 169, 0, 0.14);
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 0.74rem;
  letter-spacing: 0.1em;
  cursor: pointer;
}

.naos-stage-viewport {
  position: relative;
  height: 490px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.naos-moon-fragment {
  position: absolute;
  width: 165px;
  height: 225px;
  background-repeat: no-repeat;
  opacity: 0.82;
  filter: drop-shadow(0 14px 28px rgba(0, 0, 0, 0.75));
  transition: transform 0.35s ease;
  z-index: 1;
}

.naos-moon-fragment.moon-left {
  left: 3%;
}

.naos-moon-fragment.moon-right {
  right: 3%;
}

.naos-central-sanctuary {
  position: relative;
  height: 100%;
  min-width: 320px;
  overflow: hidden;
  z-index: 3;
  transition: width 0.25s ease-out;
  filter: drop-shadow(0 20px 50px rgba(0, 0, 0, 0.85));
}

.naos-temple-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.3s ease-out;
}

.naos-cosmic-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 48%, rgba(4, 12, 16, 0.9) 100%);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 2rem;
  text-align: center;
}

.cella-kicker {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  color: var(--accent-gold);
}

.cella-headline {
  font-family: var(--font-editorial);
  font-style: italic;
  font-size: clamp(1.3rem, 2.3vw, 1.85rem);
  font-weight: 400;
  color: var(--text-primary);
  margin-top: 0.3rem;
}

/* Monograph & Patronage Ledger */
.monograph-ledger-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.95fr;
  gap: 2rem;
}

.ledger-reliquary-box,
.ledger-patronage-box {
  background: rgba(12, 36, 43, 0.65);
  border: 1px solid var(--border-brass);
  border-radius: 24px;
  padding: 1.85rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.ledger-box-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.ledger-kicker {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
}

.ledger-title {
  font-family: var(--font-display);
  font-size: 1.45rem;
  margin-top: 0.2rem;
}

.btn-collect-all-mini {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.42rem 0.85rem;
  border-radius: 999px;
  border: 1px solid var(--accent-coral);
  background: rgba(255, 110, 122, 0.14);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 0.66rem;
  cursor: pointer;
}

.ledger-specimens-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.85rem;
}

.ledger-specimen-slot {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem;
  border-radius: 16px;
  border: 1px solid var(--border-subtle);
  background: rgba(6, 21, 25, 0.55);
  transition: opacity 0.25s ease;
}

.ledger-specimen-slot.locked {
  opacity: 0.48;
  filter: grayscale(0.65);
}

.slot-medallion {
  width: 56px;
  height: 62px;
  background-repeat: no-repeat;
  flex-shrink: 0;
}

.slot-meta {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
}

.slot-num {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  color: var(--accent-gold);
}

.slot-name {
  font-family: var(--font-display);
  font-size: 0.8rem;
}

.slot-status {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  color: var(--accent-coral);
}

.ledger-prose {
  font-size: 1.05rem;
  color: var(--text-muted);
}

.patronage-form {
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.form-field label {
  font-family: var(--font-mono);
  font-size: 0.64rem;
  letter-spacing: 0.14em;
  color: var(--accent-gold);
}

.elysian-text-input {
  width: 100%;
  padding: 0.82rem 1rem;
  border-radius: 12px;
  border: 1px solid var(--border-brass);
  background: rgba(6, 21, 25, 0.8);
  color: var(--text-primary);
  font-family: var(--font-editorial);
  font-size: 1.05rem;
  outline: none;
}

.elysian-text-input:focus {
  border-color: var(--accent-gold);
  box-shadow: 0 0 0 2px rgba(244, 169, 0, 0.22);
}

.sanctuary-city-pills {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.45rem;
}

.city-pill-btn {
  padding: 0.55rem 0.75rem;
  border-radius: 10px;
  border: 1px solid var(--border-subtle);
  background: rgba(6, 21, 25, 0.55);
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.72rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.city-pill-btn.active {
  border-color: var(--accent-gold);
  background: rgba(244, 169, 0, 0.18);
  color: var(--text-primary);
}

.btn-elysian-primary.full-width {
  width: 100%;
}

.patronage-confirmation-card {
  padding: 1.5rem;
  border-radius: 18px;
  border: 1px solid var(--accent-gold);
  background: rgba(244, 169, 0, 0.1);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.65rem;
}

.confirm-icon {
  color: var(--accent-gold);
}

.confirm-heading {
  font-family: var(--font-display);
  font-size: 1.15rem;
}

.confirm-detail {
  font-size: 1rem;
  color: var(--text-muted);
}

/* ==========================================================================
   COLOPHON FOOTER
   ========================================================================== */

.elysian-colophon {
  background: rgba(4, 12, 15, 0.96);
  padding-bottom: 3.5rem;
}

.colophon-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 2.5rem 1.75rem 0;
  display: flex;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}

.colophon-crest {
  font-family: var(--font-display);
  font-size: 1rem;
  letter-spacing: 0.24em;
  color: var(--accent-gold);
}

.colophon-motto {
  font-size: 1.05rem;
  color: var(--text-muted);
  margin-top: 0.35rem;
}

.colophon-atm-status {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--accent-coral);
  margin-top: 0.5rem;
}

.plates-heading {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
  display: block;
  margin-bottom: 0.5rem;
}

.plates-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--text-muted);
}

.plates-list span {
  color: var(--text-primary);
}

/* ==========================================================================
   RESPONSIVE BREAKPOINTS (TABLET & MOBILE)
   ========================================================================== */

@media (max-width: 1140px) {
  .hero-layout-container,
  .dissection-workbench,
  .alembic-transmutation-bench,
  .monograph-ledger-grid,
  .section-title-split {
    grid-template-columns: 1fr;
  }

  .editions-totem-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .prism-telemetry-footer {
    grid-template-columns: 1fr;
    text-align: left;
  }

  .summary-coord-block {
    text-align: left;
  }
}

@media (max-width: 768px) {
  .header-inner {
    padding: 0.65rem 1rem;
  }

  .telemetry-pill {
    display: none;
  }

  .archival-nav {
    width: 100%;
    justify-content: space-between;
    overflow-x: auto;
  }

  .hero-wunderkammer {
    padding: 2rem 1rem 3.5rem;
  }

  .instrument-row-split {
    grid-template-columns: 1fr;
  }

  .hero-collage-stage {
    min-height: 500px;
  }

  .astrolabe-halo-outer {
    width: 340px;
    height: 340px;
  }

  .ocular-portal-shell {
    height: 430px;
  }

  .satellite-image-crop {
    width: 76px;
    height: 88px;
  }

  .extracted-medallions-strip {
    grid-template-columns: repeat(3, 1fr);
  }

  .editions-totem-grid {
    grid-template-columns: 1fr;
  }

  .paravent-folding-stage {
    flex-direction: column;
    height: 680px;
  }

  .ledger-specimens-grid,
  .sanctuary-city-pills {
    grid-template-columns: 1fr;
  }

  .composite-emblem-stage {
    width: 270px;
    height: 270px;
  }

  .emblem-layer {
    width: 250px;
    height: 250px;
  }
}

/* ==========================================================================
   MAISON ELYSIAN — SURREALIST EDITORIAL LUXURY DESIGN SYSTEM
   ========================================================================== */

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --font-display: 'Cinzel', 'Cormorant Garamond', Georgia, serif;
  --font-decorative: 'Cinzel Decorative', 'Cinzel', serif;
  --font-editorial: 'Cormorant Garamond', 'Instrument Serif', Georgia, serif;
  --font-mono: 'JetBrains Mono', monospace;

  --bg-primary: #061519;
  --bg-elevated: #0c242b;
  --accent-gold: #f4a900;
  --accent-coral: #ff6e7a;
  --text-primary: #f6f2e9;
  --text-muted: #99b3b9;
  --glow-aura: rgba(244, 169, 0, 0.24);
  --border-brass: rgba(244, 169, 0, 0.28);
  --border-subtle: rgba(246, 242, 233, 0.12);
}

html {
  scroll-behavior: smooth;
  background-color: #061519;
  color: #f6f2e9;
}

body {
  font-family: var(--font-editorial);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

.elysian-universe {
  min-height: 100vh;
  background:
    radial-gradient(circle at 75% 15%, var(--glow-aura), transparent 45%),
    radial-gradient(circle at 18% 60%, rgba(255, 110, 122, 0.11), transparent 50%),
    linear-gradient(180deg, var(--bg-primary) 0%, var(--bg-elevated) 52%, var(--bg-primary) 100%);
  color: var(--text-primary);
  position: relative;
  transition: background-color 0.6s ease, color 0.5s ease;
}

/* Subtle tactile grain overlay */
.atmospheric-grain-overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 90;
  opacity: 0.035;
  background-image: radial-gradient(rgba(255, 255, 255, 0.75) 0.65px, transparent 0.65px);
  background-size: 3px 3px;
}

/* ==========================================================================
   FLOATING ASTROLABE HEADER
   ========================================================================== */

.surreal-header {
  position: sticky;
  top: 0;
  z-index: 100;
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  background: linear-gradient(
    180deg,
    rgba(6, 21, 25, 0.88) 0%,
    rgba(6, 21, 25, 0.68) 100%
  );
  border-bottom: 1px solid var(--border-brass);
}

.header-inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0.75rem 1.75rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.maison-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
  color: var(--text-primary);
}

.maison-emblem {
  width: 34px;
  height: 34px;
  color: var(--accent-gold);
  display: inline-flex;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

