/* Sculpted Octagonal/Pediment Stage */
.wunderkammer-clipped-stage {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9.2;
  clip-path: url(#clip-wunderkammer-stage);
  overflow: hidden;
  background: #051114;
}

.wunderkammer-pan-layer {
  position: relative;
  width: 100%;
  height: 100%;
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.wunderkammer-master-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.constellation-svg-overlay {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.specimen-pin {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1.5px solid var(--accent-gold);
  background: rgba(6, 21, 25, 0.88);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 4;
  transition: all 0.25s ease;
}

.specimen-pin:hover,
.specimen-pin.active {
  background: var(--accent-coral);
  border-color: #ffffff;
  color: #061519;
  transform: translate(-50%, -50%) scale(1.18);
  z-index: 6;
}

.pin-pulse-ring {
  position: absolute;
  inset: -6px;
  border-radius: 50%;
  border: 1px solid var(--accent-gold);
  animation: pinPulse 2.4s ease-out infinite;
  pointer-events: none;
}

@keyframes pinPulse {
  0% {
    transform: scale(0.85);
    opacity: 0.9;
  }
  100% {
    transform: scale(1.55);
    opacity: 0;
  }
}

.pin-floating-label {
  position: absolute;
  top: 112%;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  padding: 0.18rem 0.55rem;
  border-radius: 999px;
  background: rgba(6, 21, 25, 0.92);
  border: 1px solid var(--border-brass);
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 0.62rem;
  letter-spacing: 0.06em;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.specimen-pin:hover .pin-floating-label,
.specimen-pin.active .pin-floating-label {
  opacity: 1;
}

/* 6 Extracted Cut-Out Medallions Strip */
.extracted-medallions-strip {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0.8rem;
}

.medallion-cutout-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  padding: 0.65rem 0.45rem;
  border-radius: 16px;
  border: 1px solid var(--border-subtle);
  background: rgba(12, 36, 43, 0.45);
  color: var(--text-primary);
  cursor: pointer;
  transition: all 0.25s ease;
}

.medallion-cutout-card:hover,
.medallion-cutout-card.active {
  border-color: var(--accent-gold);
  background: rgba(244, 169, 0, 0.14);
  transform: translateY(-3px);
}

.medallion-shape-frame {
  position: relative;
  width: 78px;
  height: 88px;
}

.medallion-cropped-art {
  width: 100%;
  height: 100%;
  background-repeat: no-repeat;
  filter: drop-shadow(0 6px 14px rgba(0, 0, 0, 0.6));
}

.medallion-saved-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent-coral);
  color: #061519;
  font-size: 0.62rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.medallion-num {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  color: var(--accent-gold);
}

.medallion-name {
  font-family: var(--font-display);
  font-size: 0.66rem;
  text-align: center;
  line-height: 1.25;
}

/* Right Curatorial Specimen Dossier Card */
.specimen-dossier-panel {
  background: linear-gradient(160deg, rgba(12, 36, 43, 0.9), rgba(6, 21, 25, 0.96));
  border: 1px solid var(--border-brass);
  border-radius: 24px;
  padding: 1.65rem;
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
  box-shadow: 0 28px 64px rgba(0, 0, 0, 0.55);
}

.dossier-top-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.1em;
}

.dossier-number {
  color: var(--accent-gold);
}

.dossier-category {
  color: var(--accent-coral);
}

.dossier-magnifier-stage {
  position: relative;
  height: 215px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle, rgba(244, 169, 0, 0.16), transparent 70%);
  border-radius: 18px;
  border: 1px solid var(--border-subtle);
  overflow: hidden;
}

.dossier-sculpted-crop {
  width: 175px;
  height: 190px;
  background-repeat: no-repeat;
  filter: drop-shadow(0 16px 28px rgba(0, 0, 0, 0.75));
  transition: background-position 0.45s ease, clip-path 0.35s ease;
}

.dossier-coord-stamp {
  position: absolute;
  bottom: 10px;
  right: 12px;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  letter-spacing: 0.08em;
  color: var(--accent-gold);
  background: rgba(6, 21, 25, 0.85);
  padding: 0.2rem 0.5rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
}

.dossier-heading-group {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.dossier-latin {
  font-family: var(--font-editorial);
  font-style: italic;
  font-size: 0.98rem;
  color: var(--accent-coral);
}

.dossier-title {
  font-family: var(--font-display);
  font-size: 1.55rem;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

.dossier-epigraph {
  font-style: italic;
  font-size: 1.08rem;
  color: var(--accent-gold);
  border-left: 2px solid var(--accent-gold);
  padding-left: 0.85rem;
}

.dossier-curator-note {
  font-size: 1.05rem;
  color: var(--text-muted);
  line-height: 1.58;
}

.dossier-meta-block {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.meta-block-label {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  color: var(--text-muted);
}

.accord-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.accord-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  padding: 0.28rem 0.65rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
  background: rgba(244, 169, 0, 0.08);
  font-family: var(--font-display);
  font-size: 0.7rem;
  color: var(--text-primary);
}

.pigment-swatches-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
}

.pigment-chip {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.35rem 0.5rem;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid var(--border-subtle);
}

.pigment-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  flex-shrink: 0;
  border: 1px solid rgba(255, 255, 255, 0.35);
}

.pigment-info {
  display: flex;
  flex-direction: column;
}

.pigment-name {
  font-size: 0.72rem;
  line-height: 1.1;
}

.pigment-hex {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  color: var(--text-muted);
}

.btn-collect-specimen {
  margin-top: 0.35rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  padding: 0.85rem 1.2rem;
  border-radius: 999px;
  border: 1px solid var(--accent-gold);
  background: rgba(244, 169, 0, 0.14);
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 0.78rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.25s ease;
}

.btn-collect-specimen:hover {
  background: var(--accent-gold);
  color: #061519;
}

.btn-collect-specimen.collected {
  background: linear-gradient(135deg, var(--accent-coral), var(--accent-gold));
  border-color: transparent;
  color: #061519;
  font-weight: 700;
}

/* ==========================================================================
   CHAPTER III: LE PRISME DES HORIZONS (LOUVERS / ASTROLABE / PARAVENT)
   ========================================================================== */

.triptych-morph-section {
  padding: 5.5rem 1.75rem;
  max-width: 1440px;
  margin: 0 auto;
}

.prism-control-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
  padding: 1rem 1.35rem;
  border-radius: 20px;
  border: 1px solid var(--border-brass);
  background: rgba(12, 36, 43, 0.72);
  margin-bottom: 1.75rem;
}

.prism-mode-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.prism-tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.58rem 1.05rem;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.03);
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.76rem;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: all 0.25s ease;
}

.prism-tab-btn.active {
  background: var(--accent-gold);
  color: #061519;
  border-color: transparent;
  font-weight: 700;
}

.pendulum-scrubber-box {
  display: flex;
  align-items: center;
  gap: 1rem;
  min-width: 300px;
  flex: 1;
  max-width: 440px;
}

.pendulum-label {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--accent-gold);
}

.prism-stage-shell {
  position: relative;
  min-height: 540px;
  border-radius: 28px;
  border: 1px solid var(--border-brass);
  background: radial-gradient(circle at center, rgba(12, 36, 43, 0.9), rgba(4, 13, 18, 0.98));
  padding: 1.5rem;
  overflow: hidden;
  box-shadow: 0 30px 70px rgba(0, 0, 0, 0.6);
}

/* Mode 1: Fluted Column Louvers */
.louver-colonnade-stage {
  position: relative;
  height: 500px;
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 6px;
  cursor: ew-resize;
  clip-path: url(#clip-wunderkammer-stage);
}

.fluted-louver-slice {
  position: relative;
  height: 100%;
  border-radius: 999px;
  overflow: hidden;
  border: 1px solid rgba(244, 169, 0, 0.25);
  transition: transform 0.25s ease-out;
}

.louver-layer {
  position: absolute;
  inset: 0;
  background-size: 1200% 100%;
  background-repeat: no-repeat;
  transition: opacity 0.2s ease-out;
}

.fluted-specular-groove {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(0, 0, 0, 0.45) 0%,
    rgba(255, 255, 255, 0.14) 48%,
    rgba(0, 0, 0, 0.55) 100%
  );
  pointer-events: none;
}

.louver-roman-index {
  position: absolute;
  bottom: 14px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-mono);
  font-size: 0.58rem;
  color: var(--accent-gold);
  opacity: 0.75;
}

.stage-floating-whisper {
  position: absolute;
  bottom: 18px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.38rem 0.95rem;
  border-radius: 999px;
  background: rgba(6, 21, 25, 0.9);
  border: 1px solid var(--border-brass);
  font-family: var(--font-mono);
  font-size: 0.66rem;
  color: var(--accent-gold);
  pointer-events: none;
  white-space: nowrap;
}

/* Mode 2: Concentric Astrolabe Rings */
.concentric-astrolabe-stage {
  position: relative;
  height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: ew-resize;
}

.astrolabe-art-ring {
  position: absolute;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.65);
  transition: transform 0.2s ease-out;
}

.astrolabe-art-ring.ring-1 {
  width: 472px;
  height: 472px;
}

.astrolabe-art-ring.ring-2 {
  width: 364px;
  height: 364px;
}

.astrolabe-art-ring.ring-3 {
  width: 252px;
  height: 252px;
}

.astrolabe-art-ring.ring-4 {
  width: 140px;
  height: 140px;
}

.astrolabe-overlay-reticle {
  position: relative;
  width: 500px;
  height: 500px;
  pointer-events: none;
  z-index: 5;
}

/* Mode 3: Sculptural Paravent Folding Screen */
.paravent-folding-stage {
  display: flex;
  gap: 0.85rem;
  height: 500px;
  align-items: stretch;
}

.paravent-arch-panel {
  flex: 1;
  position: relative;
  cursor: pointer;
  transition: flex 0.55s cubic-bezier(0.22, 1, 0.36, 1), transform 0.45s ease;
}

.paravent-arch-panel.expanded {
  flex: 2.4;
}

.paravent-arch-mask {
  position: relative;
  width: 100%;
  height: 100%;
  clip-path: url(#clip-sanctuary-arch);
  overflow: hidden;
  background: #061519;
}

.paravent-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s ease;
}

.paravent-arch-panel:hover .paravent-img {
  transform: scale(1.06);
}

.paravent-gradient-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(6, 21, 25, 0.1) 20%, rgba(6, 21, 25, 0.92) 100%);
}

.paravent-panel-content {
  position: absolute;
  bottom: 22px;
  left: 20px;
  right: 20px;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.paravent-roman {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
}

.paravent-title {
  font-family: var(--font-display);
  font-size: 1.3rem;
  color: var(--text-primary);
}

.paravent-epoch {
  font-family: var(--font-editorial);
  font-style: italic;
  font-size: 0.95rem;
  color: var(--accent-coral);
}

.paravent-desc {
  font-size: 0.96rem;
  color: var(--text-muted);
  max-width: 48ch;
  margin-top: 0.25rem;
}

.paravent-coords {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.prism-telemetry-footer {
  margin-top: 1.4rem;
  padding: 1.25rem 1.5rem;
  border-radius: 20px;
  border: 1px solid var(--border-subtle);
  background: rgba(12, 36, 43, 0.55);
  display: grid;
  grid-template-columns: 1fr 1.4fr auto;
  gap: 1.5rem;
  align-items: center;
}

.summary-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  color: var(--accent-gold);
  border-left: 2px solid var(--accent-gold);
  padding-left: 0.5rem;
  margin-bottom: 0.25rem;
}

.summary-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
}

.summary-epoch {
  font-style: italic;
  color: var(--accent-coral);
  font-size: 0.95rem;
}

.summary-caption {
  font-size: 1.05rem;
  color: var(--text-muted);
}

.summary-coord-block {
  display: flex;
  flex-direction: column;
  text-align: right;
  font-family: var(--font-mono);
}

.coord-label {
  font-size: 0.58rem;
  color: var(--text-muted);
  letter-spacing: 0.12em;
}

.coord-value {
  font-size: 0.78rem;
  color: var(--accent-gold);
}

/* ==========================================================================
   CHAPTER IV: ALCHEMY COMPOSER & 4 ASSEMBLAGE RELIQUARIES
   ========================================================================== */

.alchemy-composer-section {
  padding: 5.5rem 1.75rem;
  max-width: 1440px;
  margin: 0 auto;
}

.editions-totem-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.35rem;
  margin-bottom: 3rem;
}

.edition-totem-card {
  background: linear-gradient(165deg, rgba(12, 36, 43, 0.78), rgba(6, 21, 25, 0.95));
  border: 1px solid var(--border-subtle);
  border-radius: 24px;
  padding: 1.35rem;
  display: flex;
  flex-direction: column;
  gap: 1.1rem;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}

.edition-totem-card:hover,
.edition-totem-card.active {
  border-color: var(--accent-gold);
  transform: translateY(-6px);
  box-shadow: 0 24px 50px rgba(0, 0, 0, 0.55);
}

.totem-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.12em;
}

.totem-roman {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.92rem;
}

.totem-volume {
  color: var(--text-muted);
}

.totem-art-assemblage {
  position: relative;
  height: 235px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.totem-halo-ring {
  position: absolute;
  width: 190px;
  height: 190px;
  border-radius: 50%;
  border: 1px dashed;
  opacity: 0.45;
  animation: slowAstrolabeRotate 45s linear infinite;
}

.totem-primary-vessel {
  width: 168px;
  height: 210px;
  background-repeat: no-repeat;
  z-index: 2;
  filter: drop-shadow(0 16px 28px rgba(0, 0, 0, 0.75));
  transition: transform 0.4s ease;
}

.edition-totem-card:hover .totem-primary-vessel {
  transform: scale(1.06);
}

.totem-secondary-seal {
  position: absolute;
  bottom: 10px;
  right: 16px;
  width: 74px;
  height: 74px;
  background-repeat: no-repeat;
  z-index: 3;
  filter: drop-shadow(0 8px 18px rgba(0, 0, 0, 0.8));
}

.totem-rarity-tag {
  position: absolute;
  bottom: 6px;
  left: 10px;
  z-index: 4;
  padding: 0.18rem 0.55rem;
  border-radius: 999px;
  background: rgba(6, 21, 25, 0.9);
  border: 1px solid var(--border-brass);
  font-family: var(--font-mono);
  font-size: 0.56rem;
  color: var(--accent-gold);
}

.totem-body {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.totem-designation {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  letter-spacing: 0.12em;
  color: var(--accent-coral);
  text-transform: uppercase;
}

.totem-title {
  font-family: var(--font-display);
  font-size: 1.32rem;
  color: var(--text-primary);
}

.totem-subtitle {
  font-style: italic;
  font-size: 0.98rem;
  color: var(--accent-gold);
}

.totem-story {
  font-size: 0.96rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.totem-accord-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.32rem;
  margin-top: 0.35rem;
}

.totem-accord-pill {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  padding: 0.2rem 0.5rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-subtle);
  color: var(--text-primary);
}

/* Alembic Transmutation Workbench */
.alembic-transmutation-bench {
  background: linear-gradient(145deg, rgba(12, 36, 43, 0.88), rgba(5, 16, 20, 0.96));
  border: 1px solid var(--border-brass);
  border-radius: 28px;
  padding: 2.25rem;
  display: grid;
  grid-template-columns: 1.15fr 0.95fr;
  gap: 2.5rem;
