+}
+
+.telemetry-icon {
+  color: var(--accent-gold);
+}
+
+.atmosphere-switcher {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.25rem;
+  padding: 0.2rem;
+  border-radius: 999px;
+  border: 1px solid var(--border-brass);
+  background: rgba(0, 0, 0, 0.32);
+}
+
+.atm-dot-btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.3rem;
+  padding: 0.24rem 0.52rem;
+  border-radius: 999px;
+  border: none;
+  background: transparent;
+  color: var(--text-muted);
+  cursor: pointer;
+  font-family: var(--font-mono);
+  font-size: 0.65rem;
+  transition: all 0.2s ease;
+}
+
+.atm-dot-btn.active {
+  background: rgba(244, 169, 0, 0.22);
+  color: var(--text-primary);
+}
+
+.atm-swatch {
+  width: 10px;
+  height: 10px;
+  border-radius: 50%;
+  display: inline-block;
+}
+
+.relic-counter-pill {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.38rem;
+  padding: 0.34rem 0.72rem;
+  border-radius: 999px;
+  border: 1px solid rgba(255, 110, 122, 0.45);
+  background: rgba(255, 110, 122, 0.12);
+  color: var(--text-primary);
+  text-decoration: none;
+  font-family: var(--font-mono);
+  font-size: 0.68rem;
+  transition: all 0.25s ease;
+}
+
+.relic-counter-pill:hover {
+  background: rgba(255, 110, 122, 0.24);
+  transform: translateY(-1px);
+}
+
+.sound-toggle-btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.38rem;
+  padding: 0.34rem 0.72rem;
+  border-radius: 999px;
+  border: 1px solid var(--border-brass);
+  background: rgba(244, 169, 0, 0.08);
+  color: var(--accent-gold);
+  cursor: pointer;
+  font-family: var(--font-mono);
+  font-size: 0.68rem;
+  transition: all 0.25s ease;
+}
+
+.sound-toggle-btn.active {
+  background: var(--accent-gold);
+  color: #061519;
+  font-weight: 500;
+}
+
+/* ==========================================================================
+   CHAPTER I: HERO WUNDERKAMMER & DUAL-REALITY OCULAR LOUPE
+   ========================================================================== */
+
+.hero-wunderkammer {
