}

/* ==========================================================================
   CHAPTER I: HERO WUNDERKAMMER & DUAL-REALITY OCULAR LOUPE
   ========================================================================== */

.hero-wunderkammer {
  position: relative;
  min-height: calc(100vh - 64px);
  padding: 3rem 1.75rem 4.5rem;
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-architectural-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.22;
}

.grid-meridian-v {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 52%;
  width: 1px;
  background: linear-gradient(180deg, transparent, var(--accent-gold), transparent);
}

.grid-meridian-h {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--accent-gold), transparent);
}

.hero-layout-container {
  max-width: 1440px;
  width: 100%;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.05fr 1.15fr;
  gap: 3.25rem;
  align-items: center;
  position: relative;
  z-index: 2;
}

.hero-editorial-column {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.maison-archival-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  align-self: flex-start;
  padding: 0.38rem 0.9rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
  background: rgba(12, 36, 43, 0.72);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.12em;
  color: var(--accent-gold);
}

.badge-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent-coral);
  box-shadow: 0 0 10px var(--accent-coral);
}

.badge-sep {
  opacity: 0.45;
}

.badge-coord {
  color: var(--text-muted);
}

.hero-title-lockup {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.hero-overtitle {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-family: var(--font-display);
  font-size: 0.78rem;
  letter-spacing: 0.24em;
  color: var(--accent-coral);
  text-transform: uppercase;
}

.overtitle-ornament {
  color: var(--accent-gold);
}

.hero-primary-title {
  font-family: var(--font-decorative);
  font-size: clamp(2.75rem, 5.2vw, 4.9rem);
  font-weight: 700;
  line-height: 1.02;
  letter-spacing: 0.03em;
  background: linear-gradient(
    125deg,
    #ffffff 0%,
    #f6f2e9 35%,
    var(--accent-gold) 72%,
    var(--accent-coral) 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
}

.hero-subtitle-bar {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  margin-top: 0.35rem;
}

.subtitle-line {
  width: 48px;
  height: 1px;
  background: var(--accent-gold);
  flex-shrink: 0;
}

.hero-brand-declaration {
  font-family: var(--font-display);
  font-size: 0.96rem;
  letter-spacing: 0.1em;
  color: var(--text-primary);
}

.hero-brand-declaration strong {
  color: var(--accent-gold);
  letter-spacing: 0.22em;
}

.hero-lead-prose {
  font-size: 1.24rem;
  line-height: 1.62;
  color: var(--text-muted);
  max-width: 58ch;
  font-weight: 400;
}

.hero-lead-prose em {
  color: var(--text-primary);
  font-style: italic;
}

/* Interactive Instrument Panel inside Hero */
.hero-instrument-panel {
  background: linear-gradient(145deg, rgba(12, 36, 43, 0.84), rgba(6, 21, 25, 0.92));
  border: 1px solid var(--border-brass);
  border-radius: 18px;
  padding: 1.15rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.42);
}

.instrument-group {
  display: flex;
  flex-direction: column;
  gap: 0.48rem;
}

.instrument-label {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent-gold);
}

.realm-pill-selector,
.shape-pill-selector {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.realm-pill-btn,
.shape-pill-btn {
  padding: 0.42rem 0.78rem;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.03);
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.74rem;
  letter-spacing: 0.06em;
