}

.btn-collect-specimen.collected {
  background: linear-gradient(135deg, var(--accent-coral), var(--accent-gold));
  border-color: transparent;
  color: #061519;
  font-weight: 700;
}

/* ==========================================================================
   CHAPTER III: LE PRISME DES HORIZONS (LOUVERS / ASTROLABE / PARAVENT)
   ========================================================================== */

.triptych-morph-section {
  padding: 5.5rem 1.75rem;
  max-width: 1440px;
  margin: 0 auto;
}

.prism-control-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
  padding: 1rem 1.35rem;
  border-radius: 20px;
  border: 1px solid var(--border-brass);
  background: rgba(12, 36, 43, 0.72);
  margin-bottom: 1.75rem;
}

.prism-mode-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.prism-tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.58rem 1.05rem;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.03);
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.76rem;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: all 0.25s ease;
}

.prism-tab-btn.active {
  background: var(--accent-gold);
  color: #061519;
  border-color: transparent;
  font-weight: 700;
}

.pendulum-scrubber-box {
  display: flex;
  align-items: center;
  gap: 1rem;
  min-width: 300px;
  flex: 1;
  max-width: 440px;
}

.pendulum-label {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--accent-gold);
}

.prism-stage-shell {
  position: relative;
  min-height: 540px;
  border-radius: 28px;
  border: 1px solid var(--border-brass);
  background: radial-gradient(circle at center, rgba(12, 36, 43, 0.9), rgba(4, 13, 18, 0.98));
  padding: 1.5rem;
  overflow: hidden;
  box-shadow: 0 30px 70px rgba(0, 0, 0, 0.6);
}

/* Mode 1: Fluted Column Louvers */
.louver-colonnade-stage {
  position: relative;
  height: 500px;
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 6px;
  cursor: ew-resize;
  clip-path: url(#clip-wunderkammer-stage);
}

.fluted-louver-slice {
  position: relative;
  height: 100%;
  border-radius: 999px;
  overflow: hidden;
  border: 1px solid rgba(244, 169, 0, 0.25);
  transition: transform 0.25s ease-out;
}

.louver-layer {
  position: absolute;
  inset: 0;
  background-size: 1200% 100%;
  background-repeat: no-repeat;
  transition: opacity 0.2s ease-out;
}

.fluted-specular-groove {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(0, 0, 0, 0.45) 0%,
    rgba(255, 255, 255, 0.14) 48%,
    rgba(0, 0, 0, 0.55) 100%
  );
  pointer-events: none;
}

.louver-roman-index {
  position: absolute;
  bottom: 14px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-mono);
  font-size: 0.58rem;
  color: var(--accent-gold);
  opacity: 0.75;
}

.stage-floating-whisper {
  position: absolute;
  bottom: 18px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.38rem 0.95rem;
  border-radius: 999px;
  background: rgba(6, 21, 25, 0.9);
  border: 1px solid var(--border-brass);
  font-family: var(--font-mono);
  font-size: 0.66rem;
  color: var(--accent-gold);
  pointer-events: none;
  white-space: nowrap;
}

/* Mode 2: Concentric Astrolabe Rings */
.concentric-astrolabe-stage {
  position: relative;
  height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: ew-resize;
}

.astrolabe-art-ring {
  position: absolute;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.65);
  transition: transform 0.2s ease-out;
}

.astrolabe-art-ring.ring-1 {
  width: 472px;
  height: 472px;
}

.astrolabe-art-ring.ring-2 {
  width: 364px;
  height: 364px;
}

.astrolabe-art-ring.ring-3 {
  width: 252px;
  height: 252px;
}

.astrolabe-art-ring.ring-4 {
  width: 140px;
  height: 140px;
}

.astrolabe-overlay-reticle {
  position: relative;
  width: 500px;
  height: 500px;
  pointer-events: none;
  z-index: 5;
}

/* Mode 3: Sculptural Paravent Folding Screen */
.paravent-folding-stage {
  display: flex;
  gap: 0.85rem;
  height: 500px;
  align-items: stretch;
}

.paravent-arch-panel {
  flex: 1;
  position: relative;
  cursor: pointer;
  transition: flex 0.55s cubic-bezier(0.22, 1, 0.36, 1), transform 0.45s ease;
}

.paravent-arch-panel.expanded {
  flex: 2.4;
}

.paravent-arch-mask {
  position: relative;
  width: 100%;
  height: 100%;
  clip-path: url(#clip-sanctuary-arch);
  overflow: hidden;
  background: #061519;
}

.paravent-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s ease;
}

.paravent-arch-panel:hover .paravent-img {
  transform: scale(1.06);
}

.paravent-gradient-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(6, 21, 25, 0.1) 20%, rgba(6, 21, 25, 0.92) 100%);
}

.paravent-panel-content {
  position: absolute;
  bottom: 22px;
  left: 20px;
  right: 20px;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.paravent-roman {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
}

.paravent-title {
  font-family: var(--font-display);
  font-size: 1.3rem;
  color: var(--text-primary);
}

.paravent-epoch {
  font-family: var(--font-editorial);
  font-style: italic;
  font-size: 0.95rem;
  color: var(--accent-coral);
}

.paravent-desc {
  font-size: 0.96rem;
  color: var(--text-muted);
  max-width: 48ch;
  margin-top: 0.25rem;
}

.paravent-coords {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.prism-telemetry-footer {
  margin-top: 1.4rem;
  padding: 1.25rem 1.5rem;
  border-radius: 20px;
  border: 1px solid var(--border-subtle);
  background: rgba(12, 36, 43, 0.55);
  display: grid;
  grid-template-columns: 1fr 1.4fr auto;
  gap: 1.5rem;
  align-items: center;
}

.summary-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  color: var(--accent-gold);
  border-left: 2px solid var(--accent-gold);
  padding-left: 0.5rem;
  margin-bottom: 0.25rem;
}

.summary-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
}

.summary-epoch {
  font-style: italic;
  color: var(--accent-coral);
  font-size: 0.95rem;
}

.summary-caption {
  font-size: 1.05rem;
  color: var(--text-muted);
}

.summary-coord-block {
  display: flex;
  flex-direction: column;
  text-align: right;
  font-family: var(--font-mono);
}

.coord-label {
  font-size: 0.58rem;
  color: var(--text-muted);
  letter-spacing: 0.12em;
}

.coord-value {
  font-size: 0.78rem;
  color: var(--accent-gold);
}

/* ==========================================================================
   CHAPTER IV: ALCHEMY COMPOSER & 4 ASSEMBLAGE RELIQUARIES
   ========================================================================== */

.alchemy-composer-section {
  padding: 5.5rem 1.75rem;
