/* ==========================================================================
   CHAPTER V: LE SEUIL DU NAOS & PATRONAGE LEDGER
   ========================================================================== */

.naos-portal-section {
  padding: 5.5rem 1.75rem 6rem;
  max-width: 1440px;
  margin: 0 auto;
}

.naos-architectural-theatre {
  background: linear-gradient(180deg, rgba(8, 24, 30, 0.8), rgba(4, 12, 16, 0.96));
  border: 1px solid var(--border-brass);
  border-radius: 28px;
  padding: 1.5rem;
  margin-bottom: 2.5rem;
  box-shadow: 0 32px 80px rgba(0, 0, 0, 0.65);
}

.naos-aperture-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  flex-wrap: wrap;
  margin-bottom: 1.25rem;
}

.naos-slider-label {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  color: var(--accent-gold);
}

.btn-open-full-naos {
  padding: 0.48rem 1rem;
  border-radius: 999px;
  border: 1px solid var(--accent-gold);
  background: rgba(244, 169, 0, 0.14);
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 0.74rem;
  letter-spacing: 0.1em;
  cursor: pointer;
}

.naos-stage-viewport {
  position: relative;
  height: 490px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.naos-moon-fragment {
  position: absolute;
  width: 165px;
  height: 225px;
  background-repeat: no-repeat;
  opacity: 0.82;
  filter: drop-shadow(0 14px 28px rgba(0, 0, 0, 0.75));
  transition: transform 0.35s ease;
  z-index: 1;
}

.naos-moon-fragment.moon-left {
  left: 3%;
}

.naos-moon-fragment.moon-right {
  right: 3%;
}

.naos-central-sanctuary {
  position: relative;
  height: 100%;
  min-width: 320px;
  overflow: hidden;
  z-index: 3;
  transition: width 0.25s ease-out;
  filter: drop-shadow(0 20px 50px rgba(0, 0, 0, 0.85));
}

.naos-temple-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.3s ease-out;
}

.naos-cosmic-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 48%, rgba(4, 12, 16, 0.9) 100%);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 2rem;
  text-align: center;
}

.cella-kicker {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  color: var(--accent-gold);
}

.cella-headline {
  font-family: var(--font-editorial);
  font-style: italic;
  font-size: clamp(1.3rem, 2.3vw, 1.85rem);
  font-weight: 400;
  color: var(--text-primary);
  margin-top: 0.3rem;
}

/* Monograph & Patronage Ledger */
.monograph-ledger-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.95fr;
  gap: 2rem;
}

.ledger-reliquary-box,
.ledger-patronage-box {
  background: rgba(12, 36, 43, 0.65);
  border: 1px solid var(--border-brass);
  border-radius: 24px;
  padding: 1.85rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.ledger-box-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.ledger-kicker {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
}

.ledger-title {
  font-family: var(--font-display);
  font-size: 1.45rem;
  margin-top: 0.2rem;
}

.btn-collect-all-mini {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.42rem 0.85rem;
  border-radius: 999px;
  border: 1px solid var(--accent-coral);
  background: rgba(255, 110, 122, 0.14);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 0.66rem;
  cursor: pointer;
}

.ledger-specimens-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.85rem;
}

.ledger-specimen-slot {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem;
  border-radius: 16px;
  border: 1px solid var(--border-subtle);
  background: rgba(6, 21, 25, 0.55);
  transition: opacity 0.25s ease;
}

.ledger-specimen-slot.locked {
  opacity: 0.48;
  filter: grayscale(0.65);
}

.slot-medallion {
  width: 56px;
  height: 62px;
  background-repeat: no-repeat;
  flex-shrink: 0;
}

.slot-meta {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
}

.slot-num {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  color: var(--accent-gold);
}

.slot-name {
  font-family: var(--font-display);
  font-size: 0.8rem;
}

.slot-status {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  color: var(--accent-coral);
}

.ledger-prose {
  font-size: 1.05rem;
  color: var(--text-muted);
}

.patronage-form {
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.form-field label {
  font-family: var(--font-mono);
  font-size: 0.64rem;
  letter-spacing: 0.14em;
  color: var(--accent-gold);
}

.elysian-text-input {
  width: 100%;
  padding: 0.82rem 1rem;
  border-radius: 12px;
  border: 1px solid var(--border-brass);
  background: rgba(6, 21, 25, 0.8);
  color: var(--text-primary);
  font-family: var(--font-editorial);
  font-size: 1.05rem;
  outline: none;
}

.elysian-text-input:focus {
  border-color: var(--accent-gold);
  box-shadow: 0 0 0 2px rgba(244, 169, 0, 0.22);
}

.sanctuary-city-pills {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.45rem;
}

.city-pill-btn {
  padding: 0.55rem 0.75rem;
  border-radius: 10px;
  border: 1px solid var(--border-subtle);
  background: rgba(6, 21, 25, 0.55);
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.72rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.city-pill-btn.active {
  border-color: var(--accent-gold);
  background: rgba(244, 169, 0, 0.18);
  color: var(--text-primary);
}

.btn-elysian-primary.full-width {
  width: 100%;
}

.patronage-confirmation-card {
  padding: 1.5rem;
  border-radius: 18px;
  border: 1px solid var(--accent-gold);
  background: rgba(244, 169, 0, 0.1);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.65rem;
}

.confirm-icon {
  color: var(--accent-gold);
}

.confirm-heading {
  font-family: var(--font-display);
  font-size: 1.15rem;
}

.confirm-detail {
  font-size: 1rem;
  color: var(--text-muted);
}

/* ==========================================================================
   COLOPHON FOOTER
   ========================================================================== */

.elysian-colophon {
  background: rgba(4, 12, 15, 0.96);
  padding-bottom: 3.5rem;
}

.colophon-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 2.5rem 1.75rem 0;
  display: flex;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}

.colophon-crest {
  font-family: var(--font-display);
  font-size: 1rem;
  letter-spacing: 0.24em;
  color: var(--accent-gold);
}

.colophon-motto {
  font-size: 1.05rem;
  color: var(--text-muted);
  margin-top: 0.35rem;
}

.colophon-atm-status {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--accent-coral);
  margin-top: 0.5rem;
}

.plates-heading {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
  display: block;
  margin-bottom: 0.5rem;
}

.plates-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--text-muted);
}

.plates-list span {
  color: var(--text-primary);
}

/* ==========================================================================
   RESPONSIVE BREAKPOINTS (TABLET & MOBILE)
   ========================================================================== */

@media (max-width: 1140px) {
  .hero-layout-container,
  .dissection-workbench,
  .alembic-transmutation-bench,
  .monograph-ledger-grid,
  .section-title-split {
    grid-template-columns: 1fr;
  }

  .editions-totem-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .prism-telemetry-footer {
    grid-template-columns: 1fr;
    text-align: left;
  }

  .summary-coord-block {
    text-align: left;
  }
}

@media (max-width: 768px) {
  .header-inner {
    padding: 0.65rem 1rem;
  }

  .telemetry-pill {
    display: none;
  }

  .archival-nav {
    width: 100%;
    justify-content: space-between;
    overflow-x: auto;
  }

  .hero-wunderkammer {
    padding: 2rem 1rem 3.5rem;
  }

  .instrument-row-split {
    grid-template-columns: 1fr;
  }

  .hero-collage-stage {
    min-height: 500px;
  }

  .astrolabe-halo-outer {
    width: 340px;
    height: 340px;
  }

  .ocular-portal-shell {
    height: 430px;
  }

  .satellite-image-crop {
    width: 76px;
    height: 88px;
  }

  .extracted-medallions-strip {
    grid-template-columns: repeat(3, 1fr);
  }

  .editions-totem-grid {
    grid-template-columns: 1fr;
  }

  .paravent-folding-stage {
    flex-direction: column;
    height: 680px;
  }

  .ledger-specimens-grid,
  .sanctuary-city-pills {
    grid-template-columns: 1fr;
  }

  .composite-emblem-stage {
    width: 270px;
    height: 270px;
  }

  .emblem-layer {
    width: 250px;
    height: 250px;
  }
}

