  gap: 0.48rem;
}

.instrument-label {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent-gold);
}

.realm-pill-selector,
.shape-pill-selector {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.realm-pill-btn,
.shape-pill-btn {
  padding: 0.42rem 0.78rem;
