  font-size: 0.98rem;
  color: var(--accent-coral);
}

.dossier-title {
  font-family: var(--font-display);
  font-size: 1.55rem;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

.dossier-epigraph {
  font-style: italic;
  font-size: 1.08rem;
  color: var(--accent-gold);
