  color: var(--text-primary);
}

.paravent-epoch {
  font-family: var(--font-editorial);
  font-style: italic;
  font-size: 0.95rem;
  color: var(--accent-coral);
}

.paravent-desc {
  font-size: 0.96rem;
  color: var(--text-muted);
