}

.dossier-coord-stamp {
  position: absolute;
  bottom: 10px;
  right: 12px;
  font-family: var(--font-mono);
  font-size: 0.58rem;
  letter-spacing: 0.08em;
  color: var(--accent-gold);
  background: rgba(6, 21, 25, 0.85);
  padding: 0.2rem 0.5rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
}

.dossier-heading-group {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.dossier-latin {
  font-family: var(--font-editorial);
  font-style: italic;
  font-size: 0.98rem;
  color: var(--accent-coral);
}

.dossier-title {
  font-family: var(--font-display);
  font-size: 1.55rem;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

.dossier-epigraph {
  font-style: italic;
  font-size: 1.08rem;
  color: var(--accent-gold);
  border-left: 2px solid var(--accent-gold);
  padding-left: 0.85rem;
}

.dossier-curator-note {
  font-size: 1.05rem;
  color: var(--text-muted);
  line-height: 1.58;
}

.dossier-meta-block {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.meta-block-label {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  color: var(--text-muted);
}

.accord-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.accord-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  padding: 0.28rem 0.65rem;
  border-radius: 999px;
  border: 1px solid var(--border-brass);
  background: rgba(244, 169, 0, 0.08);
  font-family: var(--font-display);
  font-size: 0.7rem;
  color: var(--text-primary);
}

.pigment-swatches-row {
