.patronage-form {
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.form-field label {
  font-family: var(--font-mono);
  font-size: 0.64rem;
  letter-spacing: 0.14em;
  color: var(--accent-gold);
}

.elysian-text-input {
  width: 100%;
  padding: 0.82rem 1rem;
  border-radius: 12px;
  border: 1px solid var(--border-brass);
  background: rgba(6, 21, 25, 0.8);
  color: var(--text-primary);
  font-family: var(--font-editorial);
  font-size: 1.05rem;
  outline: none;
}

.elysian-text-input:focus {
  border-color: var(--accent-gold);
  box-shadow: 0 0 0 2px rgba(244, 169, 0, 0.22);
}

.sanctuary-city-pills {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.45rem;
}

.city-pill-btn {
  padding: 0.55rem 0.75rem;
  border-radius: 10px;
  border: 1px solid var(--border-subtle);
  background: rgba(6, 21, 25, 0.55);
  color: var(--text-muted);
  font-family: var(--font-display);
  font-size: 0.72rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.city-pill-btn.active {
  border-color: var(--accent-gold);
  background: rgba(244, 169, 0, 0.18);
  color: var(--text-primary);
}

.btn-elysian-primary.full-width {
  width: 100%;
}

.patronage-confirmation-card {
  padding: 1.5rem;
  border-radius: 18px;
  border: 1px solid var(--accent-gold);
  background: rgba(244, 169, 0, 0.1);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.65rem;
}

.confirm-icon {
  color: var(--accent-gold);
}

.confirm-heading {
  font-family: var(--font-display);
  font-size: 1.15rem;
}

.confirm-detail {
  font-size: 1rem;
  color: var(--text-muted);
}

/* ==========================================================================
   COLOPHON FOOTER
   ========================================================================== */

.elysian-colophon {
  background: rgba(4, 12, 15, 0.96);
  padding-bottom: 3.5rem;
}

.colophon-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 2.5rem 1.75rem 0;
  display: flex;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}

.colophon-crest {
  font-family: var(--font-display);
  font-size: 1rem;
  letter-spacing: 0.24em;
  color: var(--accent-gold);
}

.colophon-motto {
  font-size: 1.05rem;
  color: var(--text-muted);
  margin-top: 0.35rem;
}

.colophon-atm-status {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--accent-coral);
  margin-top: 0.5rem;
}

.plates-heading {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.16em;
  color: var(--accent-gold);
  display: block;
  margin-bottom: 0.5rem;
}

.plates-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--text-muted);
}

.plates-list span {
  color: var(--text-primary);
}

/* ==========================================================================
   RESPONSIVE BREAKPOINTS (TABLET & MOBILE)
   ========================================================================== */

@media (max-width: 1140px) {
  .hero-layout-container,
  .dissection-workbench,
  .alembic-transmutation-bench,
  .monograph-ledger-grid,
  .section-title-split {
    grid-template-columns: 1fr;
  }

  .editions-totem-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .prism-telemetry-footer {
    grid-template-columns: 1fr;
    text-align: left;
  }

  .summary-coord-block {
    text-align: left;
  }
}

@media (max-width: 768px) {
  .header-inner {
    padding: 0.65rem 1rem;
  }

  .telemetry-pill {
    display: none;
  }

  .archival-nav {
    width: 100%;
    justify-content: space-between;
    overflow-x: auto;
    padding: 0.2rem 0.35rem;
    gap: 0.15rem;
  }

  .nav-chapter {
    padding: 0.26rem 0.48rem;
    font-size: 0.64rem;
    gap: 0.25rem;
  }

  .hero-primary-title {
    font-size: clamp(1.95rem, 7.6vw, 2.75rem);
  }

  .hero-overtitle {
    font-size: 0.64rem;
    letter-spacing: 0.14em;
    flex-wrap: wrap;
  }

  .hero-wunderkammer {
    padding: 2rem 1rem 3.5rem;
  }

  .instrument-row-split {
    grid-template-columns: 1fr;
  }

  .hero-collage-stage {
    min-height: 500px;
  }

  .astrolabe-halo-outer {
    width: 340px;
    height: 340px;
  }

  .ocular-portal-shell {
    height: 430px;
  }

  .satellite-image-crop {
    width: 76px;
    height: 88px;
  }

  .extracted-medallions-strip {
    grid-template-columns: repeat(3, 1fr);
  }

  .editions-totem-grid {
    grid-template-columns: 1fr;
  }

  .paravent-folding-stage {
    flex-direction: column;
    height: 680px;
  }

  .ledger-specimens-grid,
  .sanctuary-city-pills {
    grid-template-columns: 1fr;
  }

  .composite-emblem-stage {
    width: 270px;
    height: 270px;
  }

  .emblem-layer {
    width: 250px;
    height: 250px;
  }
}

args.command:
pnpm build && node -e '
import { spawn } from "child_process";
const srv = spawn("pnpm", ["preview", "--port", "4173", "--host", "127.0.0.1"], { stdio: "inherit" });
setTimeout(() => {
  const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
  const run = (args) => new Promise((res) => {
    const p = spawn(chrome, args, { stdio: "inherit" });
    p.on("close", res);
  });
  (async () => {
    await run(["--headless=new", "--disable-gpu", "--window-size=390,844", "--virtual-time-budget=2500", "--screenshot=public/archive/shot-mobile.png", "http://127.0.0.1:4173/"]);
    await run(["--headless=new", "--disable-gpu", "--window-size=1440,3800", "--virtual-time-budget=3000", "--screenshot=public/archive/shot-desktop.png", "http://127.0.0.1:4173/"]);
    srv.kill();
    process.exit(0);
  })();
}, 1200);
'

